#ifndef PSS_COMMON_LOG_H
#define PSS_COMMON_LOG_H

/* Timestamped, one-line-per-call logging to stderr: "<date time.ms> <tag>: msg". */
void pss_log_init(const char *tag);
void pss_log(const char *fmt, ...) __attribute__((format(printf, 1, 2)));

#endif

#include "common/log.h"

#include <stdarg.h>
#include <stdio.h>
#include <time.h>
#include <unistd.h>

static const char *log_tag = "pss";

void pss_log_init(const char *tag)
{
	log_tag = tag;
}

void pss_log(const char *fmt, ...)
{
	char line[1024];
	char ts[32] = "????-??-?? ??:??:??";
	struct timespec now = { 0, 0 };
	struct tm tm;
	va_list ap;
	size_t len;
	int n;

	if (clock_gettime(CLOCK_REALTIME, &now) == 0 && localtime_r(&now.tv_sec, &tm) != NULL)
		strftime(ts, sizeof ts, "%Y-%m-%d %H:%M:%S", &tm);

	n = snprintf(line, sizeof line, "%s.%03ld %s: ", ts, now.tv_nsec / 1000000, log_tag);
	if (n < 0)
		return;
	len = (size_t)n < sizeof line ? (size_t)n : sizeof line - 1;

	va_start(ap, fmt);
	n = vsnprintf(line + len, sizeof line - len, fmt, ap);
	va_end(ap);
	if (n < 0)
		return;
	len += (size_t)n;
	if (len > sizeof line - 2)
		len = sizeof line - 2;
	line[len++] = '\n';

	/* One write() per line so lines from concurrent daemons don't interleave. */
	if (write(STDERR_FILENO, line, len) < 0) {
		/* stderr is gone; there is nowhere left to report this. */
	}
}

#ifndef PSS_COMMON_TIME_H
#define PSS_COMMON_TIME_H

#include <stdint.h>

#define PSS_NS_PER_MS 1000000LL
#define PSS_NS_PER_S 1000000000LL

/* CLOCK_MONOTONIC for every interval/ordering decision (Design.md §5 "Time"). */
int64_t pss_mono_ns(void);
/* CLOCK_REALTIME, recorded alongside mono so a wrong wall clock can be fixed later. */
int64_t pss_wall_ns(void);

#endif

#include "common/time.h"

#include "common/log.h"

#include <errno.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static int64_t clock_ns(clockid_t id, const char *name)
{
	struct timespec ts;

	if (clock_gettime(id, &ts) != 0) {
		/* Only fails for a bad clock id or pointer: a programming error. */
		pss_log("clock_gettime(%s): %s", name, strerror(errno));
		abort();
	}
	return (int64_t)ts.tv_sec * PSS_NS_PER_S + ts.tv_nsec;
}

int64_t pss_mono_ns(void)
{
	return clock_ns(CLOCK_MONOTONIC, "CLOCK_MONOTONIC");
}

int64_t pss_wall_ns(void)
{
	return clock_ns(CLOCK_REALTIME, "CLOCK_REALTIME");
}

#ifndef PSS_COMMON_UTIL_H
#define PSS_COMMON_UTIL_H

#include <stddef.h>
#include <stdint.h>

/* $PSS_RUN_DIR (default /run/pss): sockets. */
const char *pss_run_dir(void);
/* $PSS_DATA_DIR (default /var/lib/pss): log/, clips/, state/. */
const char *pss_data_dir(void);

/* Strict decimal parse into [min, max]. Returns 0 or -1. */
int pss_parse_u32(const char *s, uint32_t min, uint32_t max, uint32_t *out);

/* Blocks the given signals and returns a nonblocking signalfd for them, or -1. */
int pss_signalfd(const int *sigs, size_t n);

/* Nonblocking CLOCK_MONOTONIC timerfd; first_ns must be > 0. Returns fd or -1. */
int pss_timerfd(int64_t first_ns, int64_t period_ns);
/* Consumes pending expirations. Returns 0 (including "none pending") or -1. */
int pss_timerfd_drain(int fd);

#endif

#include "common/util.h"

#include "common/log.h"
#include "common/time.h"

#include <errno.h>
#include <signal.h>
#include <stdlib.h>
#include <string.h>
#include <sys/signalfd.h>
#include <sys/timerfd.h>
#include <unistd.h>

static const char *env_or(const char *name, const char *def)
{
	const char *v = getenv(name);

	return (v != NULL && v[0] != '\0') ? v : def;
}

const char *pss_run_dir(void)
{
	return env_or("PSS_RUN_DIR", "/run/pss");
}

const char *pss_data_dir(void)
{
	return env_or("PSS_DATA_DIR", "/var/lib/pss");
}

int pss_parse_u32(const char *s, uint32_t min, uint32_t max, uint32_t *out)
{
	unsigned long v;
	char *end;

	if (s == NULL || s[0] < '0' || s[0] > '9')
		return -1;
	errno = 0;
	v = strtoul(s, &end, 10);
	if (errno != 0 || *end != '\0' || v < min || v > max)
		return -1;
	*out = (uint32_t)v;
	return 0;
}

int pss_signalfd(const int *sigs, size_t n)
{
	sigset_t set;
	int fd;

	sigemptyset(&set);
	for (size_t i = 0; i < n; i++)
		sigaddset(&set, sigs[i]);
	if (sigprocmask(SIG_BLOCK, &set, NULL) != 0) {
		pss_log("sigprocmask: %s", strerror(errno));
		return -1;
	}
	fd = signalfd(-1, &set, SFD_CLOEXEC | SFD_NONBLOCK);
	if (fd < 0)
		pss_log("signalfd: %s", strerror(errno));
	return fd;
}

static struct timespec ns_to_ts(int64_t ns)
{
	struct timespec ts = { (time_t)(ns / PSS_NS_PER_S), (long)(ns % PSS_NS_PER_S) };

	return ts;
}

int pss_timerfd(int64_t first_ns, int64_t period_ns)
{
	struct itimerspec its;
	int fd;

	fd = timerfd_create(CLOCK_MONOTONIC, TFD_CLOEXEC | TFD_NONBLOCK);
	if (fd < 0) {
		pss_log("timerfd_create: %s", strerror(errno));
		return -1;
	}
	its.it_value = ns_to_ts(first_ns);
	its.it_interval = ns_to_ts(period_ns);
	if (timerfd_settime(fd, 0, &its, NULL) != 0) {
		pss_log("timerfd_settime: %s", strerror(errno));
		close(fd);
		return -1;
	}
	return fd;
}

int pss_timerfd_drain(int fd)
{
	uint64_t expirations;
	ssize_t r = read(fd, &expirations, sizeof expirations);

	if (r == (ssize_t)sizeof expirations || (r < 0 && errno == EAGAIN))
		return 0;
	pss_log("timerfd read: %s", r < 0 ? strerror(errno) : "short read");
	return -1;
}

#ifndef PSS_COMMON_IPC_H
#define PSS_COMMON_IPC_H

/*
 * Daemon <-> hub messages over AF_UNIX SOCK_SEQPACKET (Design.md §2): one
 * fixed-size struct per packet, so boundaries are preserved and a dead peer
 * shows up as EOF/EPIPE. All processes run on the same Pi, so the struct is
 * sent in native layout.
 */

#include <stddef.h>
#include <stdint.h>

#define PSS_IPC_VER 1
#define PSS_NBANDS 8

enum pss_role {
	PSS_ROLE_NONE = 0,
	PSS_ROLE_PIR = 1,
	PSS_ROLE_CAM = 2,
	PSS_ROLE_MIC = 3,
};

enum pss_msg_type {
	PSS_MSG_HELLO = 1,	/* daemon -> hub, first message */
	PSS_MSG_HEARTBEAT,	/* daemon -> hub, every 5 s */
	PSS_MSG_PIR_EDGE,	/* pird -> hub */
	PSS_MSG_CAM_TRIGGER,	/* hub -> camd */
	PSS_MSG_CAM_DONE,	/* camd -> hub */
	PSS_MSG_MIC_FRAME,	/* micd -> hub, 50 Hz */
};

struct pss_msg {
	uint16_t type;
	uint16_t ver;
	uint32_t seq;
	int64_t mono_ns;	/* CLOCK_MONOTONIC; for PIR edges, the kernel's edge timestamp */
	union {
		struct { uint32_t role; uint32_t pid; } hello;
		struct { uint64_t dropped; uint64_t count; } hb;
		struct { uint32_t rising; uint32_t pad; } pir;
		struct { uint64_t event_id; uint32_t frames; uint32_t interval_ms; } cam_trigger;
		/* status: 0 ok, >0 rpicam exit code (128+sig if killed), <0 -errno in camd */
		struct { uint64_t event_id; int32_t status; uint32_t frames; } cam_done;
		struct { float rms; float flux; float band[PSS_NBANDS]; } mic;
	} u;
};

const char *pss_role_name(uint32_t role);

/* Zeroes *m (no uninitialised padding on the wire), sets type and mono_ns = now. */
void pss_msg_init(struct pss_msg *m, uint16_t type);

/* "$PSS_RUN_DIR/hub.sock". Returns 0 or -1 (path too long). */
int ipc_sock_path(char *buf, size_t n);

/* Nonblocking listening socket at path (stale socket file removed). fd or -1, logged. */
int ipc_listen(const char *path);
/* Nonblocking connected socket. fd or -1 with errno set; not logged (callers retry). */
int ipc_connect(const char *path);

/* 0 or -1 with errno. */
int ipc_send(int fd, struct pss_msg *m);
/* 1 = message, 0 = peer closed, -1 = error with errno (EAGAIN, EBADMSG size, EPROTO version). */
int ipc_recv(int fd, struct pss_msg *m);

#endif

#include "common/ipc.h"

#include "common/log.h"
#include "common/time.h"
#include "common/util.h"

#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/un.h>
#include <unistd.h>

const char *pss_role_name(uint32_t role)
{
	switch (role) {
	case PSS_ROLE_PIR: return "pird";
	case PSS_ROLE_CAM: return "camd";
	case PSS_ROLE_MIC: return "micd";
	default: return "unknown";
	}
}

void pss_msg_init(struct pss_msg *m, uint16_t type)
{
	memset(m, 0, sizeof *m);
	m->type = type;
	m->mono_ns = pss_mono_ns();
}

int ipc_sock_path(char *buf, size_t n)
{
	const char *dir = pss_run_dir();
	int r = snprintf(buf, n, "%s/hub.sock", dir);

	if (r < 0 || (size_t)r >= n || (size_t)r >= sizeof(((struct sockaddr_un *)0)->sun_path)) {
		pss_log("ipc: socket path under %s is too long", dir);
		return -1;
	}
	return 0;
}

static int fill_addr(struct sockaddr_un *a, const char *path)
{
	size_t len = strlen(path);

	memset(a, 0, sizeof *a);
	a->sun_family = AF_UNIX;
	if (len >= sizeof a->sun_path) {
		errno = ENAMETOOLONG;
		return -1;
	}
	memcpy(a->sun_path, path, len + 1);
	return 0;
}

int ipc_listen(const char *path)
{
	struct sockaddr_un a;
	int fd;

	if (fill_addr(&a, path) != 0) {
		pss_log("ipc: %s: %s", path, strerror(errno));
		return -1;
	}
	if (unlink(path) != 0 && errno != ENOENT) {
		pss_log("ipc: unlink %s: %s", path, strerror(errno));
		return -1;
	}
	fd = socket(AF_UNIX, SOCK_SEQPACKET | SOCK_CLOEXEC | SOCK_NONBLOCK, 0);
	if (fd < 0) {
		pss_log("ipc: socket: %s", strerror(errno));
		return -1;
	}
	if (bind(fd, (struct sockaddr *)&a, sizeof a) != 0) {
		pss_log("ipc: bind %s: %s", path, strerror(errno));
		goto fail;
	}
	if (listen(fd, 8) != 0) {
		pss_log("ipc: listen %s: %s", path, strerror(errno));
		goto fail;
	}
	return fd;
fail:
	close(fd);
	return -1;
}

int ipc_connect(const char *path)
{
	struct sockaddr_un a;
	int fd, saved;

	if (fill_addr(&a, path) != 0)
		return -1;
	fd = socket(AF_UNIX, SOCK_SEQPACKET | SOCK_CLOEXEC | SOCK_NONBLOCK, 0);
	if (fd < 0)
		return -1;
	if (connect(fd, (struct sockaddr *)&a, sizeof a) != 0) {
		saved = errno;
		close(fd);
		errno = saved;
		return -1;
	}
	return fd;
}

int ipc_send(int fd, struct pss_msg *m)
{
	ssize_t n;

	m->ver = PSS_IPC_VER;
	do
		n = send(fd, m, sizeof *m, MSG_NOSIGNAL);
	while (n < 0 && errno == EINTR);
	if (n < 0)
		return -1;
	if ((size_t)n != sizeof *m) {
		errno = EMSGSIZE;
		return -1;
	}
	return 0;
}

int ipc_recv(int fd, struct pss_msg *m)
{
	ssize_t n;

	/* MSG_TRUNC: report the real packet length so oversize packets are caught. */
	do
		n = recv(fd, m, sizeof *m, MSG_TRUNC);
	while (n < 0 && errno == EINTR);
	if (n < 0)
		return -1;
	if (n == 0)
		return 0;
	if ((size_t)n != sizeof *m) {
		errno = EBADMSG;
		return -1;
	}
	if (m->ver != PSS_IPC_VER) {
		errno = EPROTO;
		return -1;
	}
	return 1;
}

#ifndef PSS_COMMON_CLIENT_H
#define PSS_COMMON_CLIENT_H

/*
 * Sensor-daemon side of the hub connection: connect with backoff, say HELLO,
 * and drop (and count) messages while the hub is away (Design.md §6, hub row).
 */

#include "common/ipc.h"

#include <stdint.h>

struct pss_client {
	int fd;			/* -1 while disconnected */
	uint32_t role;
