#include "common/client.h"

#include "common/log.h"
#include "common/time.h"

#include <errno.h>
#include <string.h>
#include <unistd.h>

#define BACKOFF_MIN_NS (100 * PSS_NS_PER_MS)
#define BACKOFF_MAX_NS (5 * PSS_NS_PER_S)

