{
	struct pss_msg m;
	int fd;

	if (c->fd >= 0 || now_ns < c->next_try_ns)
		return 0;

	fd = ipc_connect(c->path);
	if (fd < 0) {
		if (!c->warned) {
			pss_log("hub %s unreachable (%s); retrying", c->path, strerror(errno));
			c->warned = 1;
		}
