	int fd;

	if (create && mkdirat(parent_fd, name, 0755) != 0 && errno != EEXIST) {
		pss_log("store: mkdir %s: %s", name, strerror(errno));
		return -1;
	}
	fd = openat(parent_fd, name, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
	if (fd < 0)
		pss_log("store: open %s: %s", name, strerror(errno));
	return fd;
}

/* Creates segment `no` and makes its directory entry durable. */
static int create_segment(struct pss_store *s, uint32_t no)
{
	char name[16];
	int fd;

	seg_name(name, no);
	fd = openat(s->log_dir_fd, name, O_WRONLY | O_CREAT | O_EXCL | O_APPEND | O_CLOEXEC, 0644);
	if (fd < 0) {
		pss_log("store: create %s: %s", name, strerror(errno));
		return -1;
	}
	if (fsync(s->log_dir_fd) != 0) {
		pss_log("store: fsync log/: %s", strerror(errno));
		close(fd);
		return -1;
	}
	s->seg_fd = fd;
	s->seg_no = no;
	s->seg_size = 0;
	return 0;
}

int store_open(struct pss_store *s, const char *root)
{
	uint32_t *segs = NULL;
	size_t nsegs = 0;
	uint8_t *buf = NULL;
	uint64_t size = 0, valid = 0, nrec = 0, max_clip = 0;
	char name[16];
	int state_fd, ret = -1;

	memset(s, 0, sizeof *s);
	s->root_fd = s->log_dir_fd = s->clips_dir_fd = s->seg_fd = -1;
	s->next_event_id = 1;

	if (mkdir(root, 0755) != 0 && errno != EEXIST) {
		pss_log("store: mkdir %s: %s", root, strerror(errno));
		goto out;
	}
	s->root_fd = open(root, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
	if (s->root_fd < 0) {
		pss_log("store: open %s: %s", root, strerror(errno));
		goto out;
	}
	s->log_dir_fd = open_dir_at(s->root_fd, "log", 1);
	if (s->log_dir_fd < 0)
		goto out;
	s->clips_dir_fd = open_dir_at(s->root_fd, "clips", 1);
	if (s->clips_dir_fd < 0)
		goto out;
	state_fd = open_dir_at(s->root_fd, "state", 1);
	if (state_fd < 0)
		goto out;
	if (close(state_fd) != 0)
		pss_log("store: close state/: %s", strerror(errno));

	if (list_segments(s->log_dir_fd, &segs, &nsegs) != 0)
		goto out;

	for (size_t i = 0; i < nsegs; i++) {
		if (read_segment(s->log_dir_fd, segs[i], &buf, &size) != 0)
			goto out;
		valid = store_valid_prefix(buf, size, &nrec);
		if (i + 1 < nsegs && valid < size)
			pss_log("store: WARNING seg=%" PRIu32 " (not newest) has %" PRIu64
				" bytes after its last valid record; left as is", segs[i], size - valid);
		visit_records(segs[i], buf, valid, open_visitor, s);
		free(buf);
		buf = NULL;
	}

	if (nsegs == 0) {
		if (create_segment(s, 1) != 0)
			goto out;
	} else {
		uint32_t newest = segs[nsegs - 1];

		seg_name(name, newest);
		s->seg_fd = openat(s->log_dir_fd, name, O_WRONLY | O_APPEND | O_CLOEXEC);
		if (s->seg_fd < 0) {
			pss_log("store: open %s for append: %s", name, strerror(errno));
			goto out;
		}
		/* valid/size/nrec still describe the newest segment from the loop. */
		if (valid < size) {
			if (ftruncate(s->seg_fd, (off_t)valid) != 0) {
				pss_log("store: ftruncate %s: %s", name, strerror(errno));
				goto out;
			}
			if (fsync(s->seg_fd) != 0) {
				pss_log("store: fsync %s: %s", name, strerror(errno));
				goto out;
			}
		}
		s->seg_no = newest;
		s->seg_size = valid;
	}
	s->recovered.seg_no = s->seg_no;
	s->recovered.valid_records = nsegs ? nrec : 0;
	s->recovered.truncated_bytes = nsegs ? size - valid : 0;
	pss_log("store: recovered seg=%" PRIu32 " valid=%" PRIu64 " truncated_bytes=%" PRIu64,
		s->recovered.seg_no, s->recovered.valid_records, s->recovered.truncated_bytes);

	if (clip_cleanup_tmp(s->clips_dir_fd, &s->recovered.tmp_removed) != 0)
		goto out;
	if (clip_max_id(s->clips_dir_fd, &max_clip) != 0)
		goto out;
	if (max_clip >= s->next_event_id)
		s->next_event_id = max_clip + 1;
	ret = 0;
out:
	free(buf);
	free(segs);
	if (ret != 0)
		store_close(s);
	return ret;
}

static int write_all(int fd, const uint8_t *p, size_t len)
{
	while (len > 0) {
		ssize_t w = write(fd, p, len);

		if (w < 0 && errno == EINTR)
			continue;
		if (w < 0)
			return -1;
		p += w;
		len -= (size_t)w;
	}
	return 0;
}

static int rollover(struct pss_store *s)
{
	char name[16];

	seg_name(name, s->seg_no);
	if (fdatasync(s->seg_fd) != 0) {
		pss_log("store: fdatasync %s: %s", name, strerror(errno));
		return -1;
	}
	if (close(s->seg_fd) != 0) {
		pss_log("store: close %s: %s", name, strerror(errno));
		s->seg_fd = -1;
		return -1;
	}
	s->seg_fd = -1;
	if (create_segment(s, s->seg_no + 1) != 0)
		return -1;
	pss_log("store: rolled over to seg=%" PRIu32, s->seg_no);
	return 0;
}

int store_append(struct pss_store *s, uint16_t type, const void *payload, uint32_t len)
{
	uint16_t ver = PSS_REC_VER;
	uint32_t crc;
	size_t total = PSS_REC_HDR + (size_t)len + PSS_REC_TRAILER;

	if (len > PSS_REC_MAX_PAYLOAD) {
		pss_log("store: record type %u too large (%" PRIu32 " bytes)", type, len);
		errno = EMSGSIZE;
		return -1;
	}
	if (s->seg_fd < 0) {
		pss_log("store: append with no open segment");
		errno = EBADF;
		return -1;
	}
	if (s->seg_size > 0 && s->seg_size + total > PSS_SEG_MAX && rollover(s) != 0)
		return -1;

	memcpy(s->buf, &len, 4);
	memcpy(s->buf + 4, &type, 2);
	memcpy(s->buf + 6, &ver, 2);
	if (len > 0)
		memcpy(s->buf + PSS_REC_HDR, payload, len);
	crc = pss_crc32(s->buf, PSS_REC_HDR + len);
	memcpy(s->buf + PSS_REC_HDR + len, &crc, 4);

	if (write_all(s->seg_fd, s->buf, total) != 0) {
		int saved = errno;

		pss_log("store: write seg=%" PRIu32 ": %s", s->seg_no, strerror(saved));
		/* Don't leave a torn record for the next append to follow. */
		if (ftruncate(s->seg_fd, (off_t)s->seg_size) != 0)
			pss_log("store: ftruncate after failed write: %s", strerror(errno));
		errno = saved;
		return -1;
	}
	s->seg_size += total;
	return 0;
}

int store_sync(struct pss_store *s)
{
	if (fdatasync(s->seg_fd) != 0) {
		pss_log("store: fdatasync seg=%" PRIu32 ": %s", s->seg_no, strerror(errno));
		return -1;
	}
	return 0;
}

static void close_fd(int *fd, const char *what)
{
	if (*fd >= 0 && close(*fd) != 0)
		pss_log("store: close %s: %s", what, strerror(errno));
	*fd = -1;
}

void store_close(struct pss_store *s)
{
	close_fd(&s->seg_fd, "segment");
	close_fd(&s->clips_dir_fd, "clips/");
	close_fd(&s->log_dir_fd, "log/");
	close_fd(&s->root_fd, "data dir");
}

int store_scan(const char *root, store_visit_fn fn, void *arg)
{
	uint32_t *segs = NULL;
	size_t nsegs = 0;
	uint8_t *buf = NULL;
	uint64_t size, valid;
	int root_fd, log_fd = -1, ret = -1;

	root_fd = open(root, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
	if (root_fd < 0) {
		pss_log("store: open %s: %s", root, strerror(errno));
		return -1;
	}
	log_fd = open_dir_at(root_fd, "log", 0);
	if (log_fd < 0)
		goto out;
	if (list_segments(log_fd, &segs, &nsegs) != 0)
		goto out;
	ret = 0;
	for (size_t i = 0; i < nsegs && ret == 0; i++) {
		if (read_segment(log_fd, segs[i], &buf, &size) != 0) {
			ret = -1;
			break;
		}
		valid = store_valid_prefix(buf, size, NULL);
		ret = visit_records(segs[i], buf, valid, fn, arg);
		free(buf);
		buf = NULL;
	}
out:
	free(segs);
	close_fd(&log_fd, "log/");
	close_fd(&root_fd, "data dir");
	return ret;
}

#ifndef PSS_STORE_CLIP_H
#define PSS_STORE_CLIP_H

/*
 * Mechanism D, clip store (Design.md §5): a burst is written into
 * clips/<id>.dir.tmp, then committed by fsync(files) -> fsync(tmp dir) ->
 * rename to clips/<id>.dir -> fsync(clips/). Anything still named *.tmp at
 * startup is an interrupted write and is deleted.
 */

#include <stddef.h>
#include <stdint.h>

/* "<id>.dir.tmp" / "<id>.dir". Return 0 or -1 if buf is too small. */
int clip_tmp_name(char *buf, size_t n, uint64_t event_id);
int clip_final_name(char *buf, size_t n, uint64_t event_id);

/* Makes the burst durable under its final name; *n_images = number of *.jpg. 0 or -1. */
int clip_commit(int clips_dir_fd, uint64_t event_id, uint32_t *n_images);
/* Removes clips/<id>.dir.tmp if present. 0 or -1. */
int clip_discard(int clips_dir_fd, uint64_t event_id);
/* Removes every *.tmp entry (file or one-level dir), logging each. 0 or -1. */
int clip_cleanup_tmp(int clips_dir_fd, uint32_t *removed);
/* Highest <id> among committed clips/<id>.dir (0 if none). 0 or -1. */
int clip_max_id(int clips_dir_fd, uint64_t *max_id);

/*
 * Evicts the oldest committed clips until used + need_bytes <= quota_bytes.
 * Returns 0 (room made), 1 (filesystem free space would drop below floor_pct:
 * clips disabled, event records still go through), or -1 on error.
 */
int clip_enforce_quota(int clips_dir_fd, uint64_t quota_bytes, uint64_t need_bytes,
		       uint32_t floor_pct, uint32_t *evicted);

#endif

#include "store/clip.h"

#include "common/log.h"
#include "store/dirlist.h"

#include <errno.h>
#include <fcntl.h>
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/statvfs.h>
#include <unistd.h>

static int has_suffix(const char *s, const char *suffix)
{
	size_t n = strlen(s), m = strlen(suffix);

	return n >= m && strcmp(s + n - m, suffix) == 0;
}

int clip_tmp_name(char *buf, size_t n, uint64_t event_id)
{
	int r = snprintf(buf, n, "%" PRIu64 ".dir.tmp", event_id);

	return (r < 0 || (size_t)r >= n) ? -1 : 0;
}

int clip_final_name(char *buf, size_t n, uint64_t event_id)
{
	int r = snprintf(buf, n, "%" PRIu64 ".dir", event_id);

	return (r < 0 || (size_t)r >= n) ? -1 : 0;
}

/* Parses "<digits>.dir" exactly. */
static int parse_final_name(const char *name, uint64_t *id)
{
	uint64_t v = 0;
	size_t len = strlen(name), i;

	if (len < 5 || strcmp(name + len - 4, ".dir") != 0)
		return -1;
	for (i = 0; i < len - 4; i++) {
		if (name[i] < '0' || name[i] > '9')
			return -1;
		v = v * 10 + (uint64_t)(name[i] - '0');
	}
	*id = v;
	return 0;
}

/* Removes a directory whose entries are all plain files (our burst dirs). */
static int remove_dir_at(int parent_fd, const char *name)
{
	struct dirlist dl;
	int fd, ret = -1;

	fd = openat(parent_fd, name, O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC);
	if (fd < 0) {
		pss_log("clip: open %s: %s", name, strerror(errno));
		return -1;
	}
	if (dirlist_read(fd, &dl) != 0)
		goto out;
	for (size_t i = 0; i < dl.n; i++) {
		if (unlinkat(fd, dl.names[i], 0) != 0) {
			pss_log("clip: unlink %s/%s: %s", name, dl.names[i], strerror(errno));
			dirlist_free(&dl);
			goto out;
		}
	}
	dirlist_free(&dl);
	if (unlinkat(parent_fd, name, AT_REMOVEDIR) != 0) {
		pss_log("clip: rmdir %s: %s", name, strerror(errno));
		goto out;
	}
	ret = 0;
out:
	if (close(fd) != 0)
		pss_log("clip: close %s: %s", name, strerror(errno));
	return ret;
}

/* Unlinks a file, or removes a one-level directory. */
static int remove_entry(int parent_fd, const char *name)
{
	if (unlinkat(parent_fd, name, 0) == 0)
		return 0;
	if (errno == EISDIR)
		return remove_dir_at(parent_fd, name);
	pss_log("clip: unlink %s: %s", name, strerror(errno));
	return -1;
}

int clip_commit(int clips_dir_fd, uint64_t event_id, uint32_t *n_images)
{
	char tmp[48], final[48];
	struct dirlist dl;
	uint32_t n = 0;
	int dir_fd, ret = -1;

	if (clip_tmp_name(tmp, sizeof tmp, event_id) != 0 || clip_final_name(final, sizeof final, event_id) != 0)
		return -1;
	dir_fd = openat(clips_dir_fd, tmp, O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC);
	if (dir_fd < 0) {
		pss_log("clip: open %s: %s", tmp, strerror(errno));
		return -1;
	}
	if (dirlist_read(dir_fd, &dl) != 0)
		goto out;
	for (size_t i = 0; i < dl.n; i++) {
		int fd = openat(dir_fd, dl.names[i], O_RDONLY | O_NOFOLLOW | O_CLOEXEC);

		if (fd < 0) {
			pss_log("clip: open %s/%s: %s", tmp, dl.names[i], strerror(errno));
			dirlist_free(&dl);
			goto out;
		}
		if (fsync(fd) != 0) {
			pss_log("clip: fsync %s/%s: %s", tmp, dl.names[i], strerror(errno));
			close(fd);
			dirlist_free(&dl);
			goto out;
		}
		if (close(fd) != 0)
			pss_log("clip: close %s/%s: %s", tmp, dl.names[i], strerror(errno));
		if (has_suffix(dl.names[i], ".jpg"))
			n++;
	}
	dirlist_free(&dl);
	if (fsync(dir_fd) != 0) {
		pss_log("clip: fsync %s: %s", tmp, strerror(errno));
		goto out;
	}
	if (renameat(clips_dir_fd, tmp, clips_dir_fd, final) != 0) {
		pss_log("clip: rename %s -> %s: %s", tmp, final, strerror(errno));
		goto out;
	}
	if (fsync(clips_dir_fd) != 0) {
		pss_log("clip: fsync clips/: %s", strerror(errno));
		goto out;
	}
	*n_images = n;
	ret = 0;
out:
	if (close(dir_fd) != 0)
		pss_log("clip: close %s: %s", tmp, strerror(errno));
	return ret;
}

int clip_discard(int clips_dir_fd, uint64_t event_id)
{
	char tmp[48];
	struct stat st;

	if (clip_tmp_name(tmp, sizeof tmp, event_id) != 0)
		return -1;
	if (fstatat(clips_dir_fd, tmp, &st, AT_SYMLINK_NOFOLLOW) != 0) {
		if (errno == ENOENT)
			return 0;
		pss_log("clip: stat %s: %s", tmp, strerror(errno));
		return -1;
	}
	if (remove_entry(clips_dir_fd, tmp) != 0)
		return -1;
	pss_log("clip: discarded %s", tmp);
	return 0;
}

int clip_cleanup_tmp(int clips_dir_fd, uint32_t *removed)
{
	struct dirlist dl;
	int ret = 0;

	*removed = 0;
	if (dirlist_read(clips_dir_fd, &dl) != 0)
		return -1;
	for (size_t i = 0; i < dl.n; i++) {
		if (!has_suffix(dl.names[i], ".tmp"))
			continue;
		if (remove_entry(clips_dir_fd, dl.names[i]) != 0) {
			ret = -1;
			continue;
		}
		pss_log("store: removed interrupted clip %s", dl.names[i]);
		(*removed)++;
	}
	dirlist_free(&dl);
	if (*removed > 0 && fsync(clips_dir_fd) != 0) {
		pss_log("clip: fsync clips/: %s", strerror(errno));
		ret = -1;
	}
	return ret;
}

int clip_max_id(int clips_dir_fd, uint64_t *max_id)
{
	struct dirlist dl;
	uint64_t id;

	*max_id = 0;
	if (dirlist_read(clips_dir_fd, &dl) != 0)
		return -1;
	for (size_t i = 0; i < dl.n; i++)
		if (parse_final_name(dl.names[i], &id) == 0 && id > *max_id)
			*max_id = id;
	dirlist_free(&dl);
	return 0;
}

struct clip_info {
	uint64_t id;
	uint64_t bytes;
	const char *name;
};

static int cmp_clip(const void *a, const void *b)
{
	uint64_t x = ((const struct clip_info *)a)->id, y = ((const struct clip_info *)b)->id;

	return (x > y) - (x < y);
}

static int dir_bytes(int parent_fd, const char *name, uint64_t *bytes)
{
	struct dirlist dl;
	struct stat st;
	int fd, ret = -1;

	*bytes = 0;
	fd = openat(parent_fd, name, O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC);
	if (fd < 0) {
		pss_log("clip: open %s: %s", name, strerror(errno));
		return -1;
	}
	if (dirlist_read(fd, &dl) != 0)
		goto out;
	for (size_t i = 0; i < dl.n; i++) {
		if (fstatat(fd, dl.names[i], &st, AT_SYMLINK_NOFOLLOW) != 0) {
			pss_log("clip: stat %s/%s: %s", name, dl.names[i], strerror(errno));
			dirlist_free(&dl);
			goto out;
		}
		*bytes += (uint64_t)st.st_size;
	}
	dirlist_free(&dl);
	ret = 0;
out:
	if (close(fd) != 0)
		pss_log("clip: close %s: %s", name, strerror(errno));
	return ret;
}

int clip_enforce_quota(int clips_dir_fd, uint64_t quota_bytes, uint64_t need_bytes,
		       uint32_t floor_pct, uint32_t *evicted)
{
	struct dirlist dl;
	struct clip_info *clips = NULL;
	struct statvfs vfs;
	uint64_t used = 0, free_bytes, total_bytes;
	size_t n = 0;
	int ret = -1;

	*evicted = 0;
	if (dirlist_read(clips_dir_fd, &dl) != 0)
		return -1;
	if (dl.n > 0) {
		clips = malloc(dl.n * sizeof *clips);
		if (clips == NULL) {
			pss_log("clip: out of memory in quota check");
			goto out;
		}
	}
	for (size_t i = 0; i < dl.n; i++) {
		if (parse_final_name(dl.names[i], &clips[n].id) != 0)
			continue;
		if (dir_bytes(clips_dir_fd, dl.names[i], &clips[n].bytes) != 0)
			goto out;
		clips[n].name = dl.names[i];
		used += clips[n].bytes;
		n++;
	}
	if (n > 0)
		qsort(clips, n, sizeof *clips, cmp_clip);

	for (size_t i = 0; i < n && used + need_bytes > quota_bytes; i++) {
		if (remove_dir_at(clips_dir_fd, clips[i].name) != 0)
			goto out;
		pss_log("clip: quota: evicted %s (%" PRIu64 " bytes)", clips[i].name, clips[i].bytes);
		used -= clips[i].bytes;
		(*evicted)++;
	}
	if (*evicted > 0 && fsync(clips_dir_fd) != 0) {
		pss_log("clip: fsync clips/: %s", strerror(errno));
		goto out;
	}

	if (fstatvfs(clips_dir_fd, &vfs) != 0) {
		pss_log("clip: statvfs: %s", strerror(errno));
		goto out;
	}
	free_bytes = (uint64_t)vfs.f_bavail * vfs.f_frsize;
	total_bytes = (uint64_t)vfs.f_blocks * vfs.f_frsize;
	if (free_bytes < need_bytes || (free_bytes - need_bytes) * 100 < (uint64_t)floor_pct * total_bytes) {
		pss_log("store: free %.1f%% < floor %" PRIu32 "%%, clips disabled",
			total_bytes ? 100.0 * (double)free_bytes / (double)total_bytes : 0.0, floor_pct);
		ret = 1;
		goto out;
	}
	ret = 0;
out:
	free(clips);
	dirlist_free(&dl);
	return ret;
}

