#ifndef PSS_CAPTURE_PIR_LOGIC_H
#define PSS_CAPTURE_PIR_LOGIC_H

/*
 * Hardware-independent part of pird, so it is testable off the Pi.
 * HC-SR501 false-triggers for ~60 s after power-up (Design.md §6), so edges in
 * that window are not forwarded; repeated edges in the same direction (e.g.
 * a missed edge in poll mode) are dropped so the hub sees a clean rise/fall
 * sequence.
 */

#include <stdint.h>

enum pir_verdict {
	PIR_FORWARD = 0,
	PIR_WARMUP = 1,
	PIR_DUPLICATE = 2,
};

struct pir_filter {
	int64_t warmup_until_ns;
	int level;		/* 1 high, 0 low */
	uint64_t forwarded;
	uint64_t suppressed;
};

void pir_filter_init(struct pir_filter *f, int64_t start_ns, int64_t warmup_ns, int initial_level);
enum pir_verdict pir_filter_edge(struct pir_filter *f, int rising, int64_t ts_ns);

#endif

#include "capture/pir/pir_logic.h"

#include <string.h>

void pir_filter_init(struct pir_filter *f, int64_t start_ns, int64_t warmup_ns, int initial_level)
{
	memset(f, 0, sizeof *f);
	f->warmup_until_ns = start_ns + warmup_ns;
	f->level = initial_level ? 1 : 0;
}

enum pir_verdict pir_filter_edge(struct pir_filter *f, int rising, int64_t ts_ns)
{
	int level = rising ? 1 : 0;

	if (level == f->level) {
		f->suppressed++;
		return PIR_DUPLICATE;
	}
	/* Track the level even during warm-up so the first real edge is correct. */
	f->level = level;
	if (ts_ns < f->warmup_until_ns) {
		f->suppressed++;
		return PIR_WARMUP;
	}
	f->forwarded++;
	return PIR_FORWARD;
}

/* pird's edge filter: warm-up suppression and duplicate-direction suppression. */
#include "t.h"

#include "capture/pir/pir_logic.h"

#define S 1000000000LL

static void test_warmup_suppresses_then_forwards(void)
{
	struct pir_filter f;

	pir_filter_init(&f, 100 * S, 60 * S, 0);
	CHECK(pir_filter_edge(&f, 1, 110 * S) == PIR_WARMUP);
	CHECK(pir_filter_edge(&f, 0, 120 * S) == PIR_WARMUP);
	CHECK(pir_filter_edge(&f, 1, 160 * S) == PIR_FORWARD); /* boundary: warm-up over */
	CHECK(pir_filter_edge(&f, 0, 163 * S) == PIR_FORWARD);
	CHECK(f.forwarded == 2 && f.suppressed == 2);
}

static void test_level_tracked_through_warmup(void)
{
	struct pir_filter f;

	/* Rose during warm-up and is still high: the next edge must be a fall. */
	pir_filter_init(&f, 0, 60 * S, 0);
	CHECK(pir_filter_edge(&f, 1, 59 * S) == PIR_WARMUP);
	CHECK(pir_filter_edge(&f, 1, 61 * S) == PIR_DUPLICATE);
	CHECK(pir_filter_edge(&f, 0, 62 * S) == PIR_FORWARD);
}

static void test_duplicates_dropped(void)
{
	struct pir_filter f;

	pir_filter_init(&f, 0, 0, 1);
	CHECK(pir_filter_edge(&f, 1, 1 * S) == PIR_DUPLICATE);
	CHECK(pir_filter_edge(&f, 0, 2 * S) == PIR_FORWARD);
	CHECK(pir_filter_edge(&f, 0, 3 * S) == PIR_DUPLICATE);
	CHECK(pir_filter_edge(&f, 1, 4 * S) == PIR_FORWARD);
}

int main(void)
{
	T_RUN(test_warmup_suppresses_then_forwards);
	T_RUN(test_level_tracked_through_warmup);
	T_RUN(test_duplicates_dropped);
	T_END();
}

/*
 * pird: HC-SR501 PIR on a Pi 5 GPIO line (mechanism B, Design.md §3).
 *
 * Default (IRQ) mode requests the line with both-edge detection and kernel
 * CLOCK_MONOTONIC timestamps, then sleeps in poll() until the GPIO interrupt
 * delivers an edge. --poll=<ms> reads the line value on a timerfd instead;
 * it is the comparison arm for the B measurements.
 *
 * Exit codes: 0 on SIGTERM/SIGINT, 1 on error, 2 on usage, 3 when the GPIO
 * chip disappears (supervisor treats 3 as "device gone", Design.md §3 E).
 */
#include "capture/pir/pir_logic.h"
#include "common/client.h"
#include "common/log.h"
#include "common/time.h"
#include "common/util.h"

#include <errno.h>
#include <getopt.h>
#include <gpiod.h>
#include <inttypes.h>
#include <poll.h>
#include <signal.h>
#include <stdio.h>
#include <string.h>
#include <sys/signalfd.h>
#include <unistd.h>

#define EXIT_USAGE 2
#define EXIT_DEVICE_GONE 3
#define HB_PERIOD_NS (5 * PSS_NS_PER_S)
#define EVBUF_SIZE 16

struct pir_src {
	struct gpiod_chip *chip;
	struct gpiod_line_request *req;
	struct gpiod_edge_event_buffer *evbuf;
	unsigned int offset;
	uint32_t poll_ms;
	int fd;			/* line request fd (IRQ) or timerfd (poll) */
};

static void usage(void)
{
	fprintf(stderr, "usage: pird [--chip=/dev/gpiochip0] [--line=17] [--poll=MS] [--warmup=SEC]\n"
			"  --poll=0 (default) waits for GPIO edge interrupts\n");
}

static void src_close(struct pir_src *p)
{
	if (p->poll_ms > 0 && p->fd >= 0 && close(p->fd) != 0)
		pss_log("close timerfd: %s", strerror(errno));
	p->fd = -1;
	if (p->evbuf != NULL)
		gpiod_edge_event_buffer_free(p->evbuf);
	if (p->req != NULL)
		gpiod_line_request_release(p->req);
	if (p->chip != NULL)
		gpiod_chip_close(p->chip);
	p->evbuf = NULL;
	p->req = NULL;
	p->chip = NULL;
}

/* Requests the line; *level gets its current value. Returns 0, or an exit code. */
static int src_open(struct pir_src *p, const char *chip_path, int *level)
{
	struct gpiod_line_settings *ls = NULL;
	struct gpiod_line_config *lc = NULL;
	struct gpiod_request_config *rc = NULL;
	enum gpiod_line_value v;
	int ret = 1;

	p->chip = gpiod_chip_open(chip_path);
	if (p->chip == NULL) {
		pss_log("gpiod_chip_open %s: %s", chip_path, strerror(errno));
		ret = (errno == ENOENT || errno == ENODEV) ? EXIT_DEVICE_GONE : 1;
		goto out;
	}
	ls = gpiod_line_settings_new();
	lc = gpiod_line_config_new();
	rc = gpiod_request_config_new();
	if (ls == NULL || lc == NULL || rc == NULL) {
		pss_log("gpiod: out of memory");
		goto out;
	}
	if (gpiod_line_settings_set_direction(ls, GPIOD_LINE_DIRECTION_INPUT) != 0 ||
	    gpiod_line_settings_set_bias(ls, GPIOD_LINE_BIAS_PULL_UP) != 0) {
		pss_log("gpiod line settings: %s", strerror(errno));
		goto out;
	}
	if (p->poll_ms == 0 &&
	    (gpiod_line_settings_set_edge_detection(ls, GPIOD_LINE_EDGE_BOTH) != 0 ||
	     gpiod_line_settings_set_event_clock(ls, GPIOD_LINE_CLOCK_MONOTONIC) != 0)) {
		pss_log("gpiod edge settings: %s", strerror(errno));
		goto out;
	}
	if (gpiod_line_config_add_line_settings(lc, &p->offset, 1, ls) != 0) {
		pss_log("gpiod_line_config_add_line_settings: %s", strerror(errno));
		goto out;
	}
	gpiod_request_config_set_consumer(rc, "pird");
	p->req = gpiod_chip_request_lines(p->chip, rc, lc);
	if (p->req == NULL) {
		pss_log("gpiod_chip_request_lines %s line %u: %s", chip_path, p->offset, strerror(errno));
		goto out;
	}
	v = gpiod_line_request_get_value(p->req, p->offset);
	if (v == GPIOD_LINE_VALUE_ERROR) {
		pss_log("gpiod_line_request_get_value: %s", strerror(errno));
		goto out;
	}
	*level = v == GPIOD_LINE_VALUE_ACTIVE;

	if (p->poll_ms == 0) {
		p->evbuf = gpiod_edge_event_buffer_new(EVBUF_SIZE);
		if (p->evbuf == NULL) {
			pss_log("gpiod_edge_event_buffer_new: %s", strerror(errno));
			goto out;
		}
		p->fd = gpiod_line_request_get_fd(p->req);
	} else {
		int64_t period = (int64_t)p->poll_ms * PSS_NS_PER_MS;

		p->fd = pss_timerfd(period, period);
		if (p->fd < 0)
			goto out;
	}
	ret = 0;
out:
	if (rc != NULL)
		gpiod_request_config_free(rc);
	if (lc != NULL)
		gpiod_line_config_free(lc);
	if (ls != NULL)
		gpiod_line_settings_free(ls);
	if (ret != 0)
		src_close(p);
	return ret;
}

static void on_edge(struct pss_client *cl, struct pir_filter *f, int rising, int64_t ts_ns, int64_t now_ns, int irq)
{
	enum pir_verdict v = pir_filter_edge(f, rising, ts_ns);
	struct pss_msg m;

	/* In IRQ mode ts is the kernel's interrupt timestamp, so now - ts is the
	 * edge-to-userspace latency that B measures. In poll mode ts == now. */
	if (irq)
		pss_log("edge %s lat=%" PRId64 "us%s", rising ? "rise" : "fall", (now_ns - ts_ns) / 1000,
			v == PIR_WARMUP ? " (warm-up, ignored)" : v == PIR_DUPLICATE ? " (duplicate, ignored)" : "");
	else
		pss_log("edge %s (poll)%s", rising ? "rise" : "fall",
			v == PIR_WARMUP ? " (warm-up, ignored)" : v == PIR_DUPLICATE ? " (duplicate, ignored)" : "");
	if (v != PIR_FORWARD)
		return;
	pss_msg_init(&m, PSS_MSG_PIR_EDGE);
	m.mono_ns = ts_ns;
	m.u.pir.rising = rising ? 1 : 0;
	client_send(cl, &m);
}

/* Returns 0, or an exit code. */
static int src_readable(struct pir_src *p, struct pss_client *cl, struct pir_filter *f)
{
	int64_t now;

	if (p->poll_ms == 0) {
		int n = gpiod_line_request_read_edge_events(p->req, p->evbuf, EVBUF_SIZE);

		if (n < 0) {
			pss_log("gpiod_line_request_read_edge_events: %s", strerror(errno));
			return errno == ENODEV ? EXIT_DEVICE_GONE : 1;
		}
		now = pss_mono_ns();
		for (int i = 0; i < n; i++) {
			struct gpiod_edge_event *ev = gpiod_edge_event_buffer_get_event(p->evbuf, (unsigned long)i);

			on_edge(cl, f, gpiod_edge_event_get_event_type(ev) == GPIOD_EDGE_EVENT_RISING_EDGE,
				(int64_t)gpiod_edge_event_get_timestamp_ns(ev), now, 1);
		}
		return 0;
	}

	if (pss_timerfd_drain(p->fd) != 0)
		return 1;
	enum gpiod_line_value v = gpiod_line_request_get_value(p->req, p->offset);
	if (v == GPIOD_LINE_VALUE_ERROR) {
		pss_log("gpiod_line_request_get_value: %s", strerror(errno));
		return errno == ENODEV ? EXIT_DEVICE_GONE : 1;
	}
	now = pss_mono_ns();
	if ((v == GPIOD_LINE_VALUE_ACTIVE) != f->level)
		on_edge(cl, f, v == GPIOD_LINE_VALUE_ACTIVE, now, now, 0);
	return 0;
}

static void send_heartbeat(struct pss_client *cl, const struct pir_filter *f)
{
	struct pss_msg m;

	pss_msg_init(&m, PSS_MSG_HEARTBEAT);
	m.u.hb.dropped = cl->dropped;
	m.u.hb.count = f->forwarded;
	client_send(cl, &m);
}

int main(int argc, char **argv)
{
	static const struct option opts[] = {
		{ "chip", required_argument, NULL, 'c' },
		{ "line", required_argument, NULL, 'l' },
		{ "poll", required_argument, NULL, 'p' },
		{ "warmup", required_argument, NULL, 'w' },
		{ "help", no_argument, NULL, 'h' },
		{ NULL, 0, NULL, 0 },
	};
	const int sigs[] = { SIGINT, SIGTERM };
	const char *chip_path = "/dev/gpiochip0";
	struct pir_src src = { .fd = -1 };
	struct pss_client cl;
	struct pir_filter filter;
	uint32_t line = 17, warmup_s = 60;
	int sig_fd = -1, hb_fd = -1, level = 0, armed = 0, code = 1, opt;

	pss_log_init("pird");
	cl.fd = -1;
	while ((opt = getopt_long(argc, argv, "", opts, NULL)) != -1) {
		switch (opt) {
		case 'c': chip_path = optarg; break;
		case 'l':
			if (pss_parse_u32(optarg, 0, 1023, &line) != 0) { usage(); return EXIT_USAGE; }
			break;
		case 'p':
			if (pss_parse_u32(optarg, 0, 10000, &src.poll_ms) != 0) { usage(); return EXIT_USAGE; }
			break;
		case 'w':
			if (pss_parse_u32(optarg, 0, 600, &warmup_s) != 0) { usage(); return EXIT_USAGE; }
			break;
		default: usage(); return opt == 'h' ? 0 : EXIT_USAGE;
		}
	}
	src.offset = line;

	sig_fd = pss_signalfd(sigs, 2);
	if (sig_fd < 0)
		goto out;
	if (client_init(&cl, PSS_ROLE_PIR) != 0)
		goto out;
	code = src_open(&src, chip_path, &level);
	if (code != 0)
		goto out;
	code = 1;
	hb_fd = pss_timerfd(HB_PERIOD_NS, HB_PERIOD_NS);
	if (hb_fd < 0)
		goto out;
	pir_filter_init(&filter, pss_mono_ns(), (int64_t)warmup_s * PSS_NS_PER_S, level);
	pss_log("start pid=%d chip=%s line=%" PRIu32 " mode=%s level=%d; warm-up, edges ignored until T+%" PRIu32 "s",
		(int)getpid(), chip_path, line, src.poll_ms ? "poll" : "irq", level, warmup_s);
	if (src.poll_ms)
		pss_log("polling every %" PRIu32 " ms", src.poll_ms);

	for (;;) {
		struct pollfd pfd[4];
		int64_t now = pss_mono_ns();
		int nfds = 3, timeout;

		if (client_poll_connect(&cl, now))
			send_heartbeat(&cl, &filter);
		if (!armed && now >= filter.warmup_until_ns) {
			pss_log("warm-up over, armed (line level=%d)", filter.level);
			armed = 1;
		}

		pfd[0] = (struct pollfd){ .fd = sig_fd, .events = POLLIN };
		pfd[1] = (struct pollfd){ .fd = src.fd, .events = POLLIN };
		pfd[2] = (struct pollfd){ .fd = hb_fd, .events = POLLIN };
		if (cl.fd >= 0)
			pfd[nfds++] = (struct pollfd){ .fd = cl.fd, .events = POLLIN };
		timeout = cl.fd < 0 ? 250 : armed ? -1 : 1000;

		if (poll(pfd, (nfds_t)nfds, timeout) < 0) {
			if (errno == EINTR)
				continue;
			pss_log("poll: %s", strerror(errno));
			goto out;
		}
		if (pfd[0].revents & POLLIN) {
			struct signalfd_siginfo si;

			if (read(sig_fd, &si, sizeof si) != (ssize_t)sizeof si)
				pss_log("signalfd read: %s", strerror(errno));
			else
				pss_log("signal %u, exiting (forwarded=%" PRIu64 " dropped=%" PRIu64 ")",
					si.ssi_signo, filter.forwarded, cl.dropped);
			code = 0;
			goto out;
		}
		if (pfd[1].revents & (POLLIN | POLLERR | POLLHUP)) {
			int r = src_readable(&src, &cl, &filter);

			if (r != 0) {
				code = r;
				if (code == EXIT_DEVICE_GONE)
					pss_log("GPIO device gone; exit 3");
				goto out;
			}
		}
		if (pfd[2].revents & POLLIN) {
			if (pss_timerfd_drain(hb_fd) != 0)
				goto out;
			send_heartbeat(&cl, &filter);
		}
		if (nfds == 4 && pfd[3].revents) {
			struct pss_msg m;
			int r = ipc_recv(cl.fd, &m);

			if (r == 0)
				client_disconnect(&cl, now, "hub closed");
			else if (r < 0 && errno != EAGAIN)
				client_disconnect(&cl, now, strerror(errno));
		}
	}
out:
	client_close(&cl);
	src_close(&src);
	if (hb_fd >= 0)
		close(hb_fd);
	if (sig_fd >= 0)
		close(sig_fd);
	return code;
}

/*
 * camd: Arducam OV5647 evidence bursts (Design.md §2). On CAM_TRIGGER from the
 * hub it runs `rpicam-still --timelapse` into clips/<id>.dir.tmp and reports
 * CAM_DONE. The hub, not camd, commits or discards the burst (single writer).
 *
 * $PSS_RPICAM overrides the rpicam-still path (tests use a stand-in script).
 * Exit codes: 0 on SIGTERM/SIGINT, 1 on error, 2 on usage.
 */
#include "common/client.h"
#include "common/log.h"
#include "common/time.h"
#include "common/util.h"
#include "store/clip.h"
#include "store/dirlist.h"

#include <errno.h>
#include <fcntl.h>
#include <getopt.h>
#include <inttypes.h>
#include <limits.h>
#include <poll.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/signalfd.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <unistd.h>

#define EXIT_USAGE 2
#define HB_PERIOD_NS (5 * PSS_NS_PER_S)
#define BURST_SLACK_NS (15 * PSS_NS_PER_S)

struct burst {
	pid_t pid;		/* 0 when idle */
	uint64_t event_id;
	int64_t deadline_ns;
	int killed;
};

struct camd {
	struct pss_client cl;
	struct burst b;
	const char *rpicam;
	char clips_path[PATH_MAX];
	uint32_t width, height;
	uint64_t bursts, failures;
};

static void usage(void)
{
	fprintf(stderr, "usage: camd [--width=1296] [--height=972]\n");
}

static void reply(struct camd *c, uint64_t event_id, int32_t status, uint32_t frames)
{
	struct pss_msg m;

	pss_msg_init(&m, PSS_MSG_CAM_DONE);
	m.u.cam_done.event_id = event_id;
	m.u.cam_done.status = status;
	m.u.cam_done.frames = frames;
	if (client_send(&c->cl, &m) != 0)
		pss_log("burst %" PRIu64 ": result not delivered (hub away); hub will clean up", event_id);
}

static pid_t spawn_rpicam(const struct camd *c, const char *outpat, uint32_t frames, uint32_t interval_ms)
{
	char t_ms[16], tl_ms[16], w[16], h[16];
	char *argv[] = {
		(char *)c->rpicam, "-n", "-t", t_ms, "--timelapse", tl_ms,
		"--width", w, "--height", h, "-q", "85", "-o", (char *)outpat, NULL,
	};
	pid_t pid;

	snprintf(t_ms, sizeof t_ms, "%" PRIu32, frames * interval_ms);
	snprintf(tl_ms, sizeof tl_ms, "%" PRIu32, interval_ms);
	snprintf(w, sizeof w, "%" PRIu32, c->width);
	snprintf(h, sizeof h, "%" PRIu32, c->height);

	pid = fork();
	if (pid != 0)
		return pid; /* parent, or -1 */

	/* Child: undo the parent's blocked signals, stdin from /dev/null. */
	sigset_t none;
	int devnull;

	sigemptyset(&none);
	sigprocmask(SIG_SETMASK, &none, NULL);
	devnull = open("/dev/null", O_RDONLY);
	if (devnull >= 0 && devnull != STDIN_FILENO) {
		dup2(devnull, STDIN_FILENO);
		close(devnull);
	}
	execvp(argv[0], argv);
	dprintf(STDERR_FILENO, "camd: exec %s: %s\n", argv[0], strerror(errno));
	_exit(127);
}

static void start_burst(struct camd *c, const struct pss_msg *m, int64_t now)
{
	uint64_t id = m->u.cam_trigger.event_id;
	uint32_t frames = m->u.cam_trigger.frames, interval = m->u.cam_trigger.interval_ms;
	char tmp[48], outpat[PATH_MAX + 64];
	int clips_fd, r;
	pid_t pid;

	if (c->b.pid > 0) {
		pss_log("burst %" PRIu64 " refused: burst %" PRIu64 " still running", id, c->b.event_id);
		reply(c, id, -EBUSY, 0);
		return;
	}
	if (frames == 0 || frames > 1000 || interval == 0 || interval > 10000) {
		pss_log("burst %" PRIu64 " refused: bad parameters %" PRIu32 "x%" PRIu32 "ms", id, frames, interval);
		reply(c, id, -EINVAL, 0);
		return;
	}
	if (clip_tmp_name(tmp, sizeof tmp, id) != 0) {
		reply(c, id, -ENAMETOOLONG, 0);
		return;
	}
	r = snprintf(outpat, sizeof outpat, "%s/%s/img%%04d.jpg", c->clips_path, tmp);
	if (r < 0 || (size_t)r >= sizeof outpat) {
		pss_log("burst %" PRIu64 ": output path too long", id);
		reply(c, id, -ENAMETOOLONG, 0);
		return;
	}
	clips_fd = open(c->clips_path, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
	if (clips_fd < 0) {
		r = errno;
		pss_log("burst %" PRIu64 ": open %s: %s", id, c->clips_path, strerror(r));
		reply(c, id, -r, 0);
		return;
	}
	if (mkdirat(clips_fd, tmp, 0755) != 0) {
		r = errno;
		pss_log("burst %" PRIu64 ": mkdir %s: %s", id, tmp, strerror(r));
		close(clips_fd);
		reply(c, id, -r, 0);
		return;
	}
	if (close(clips_fd) != 0)
		pss_log("close clips/: %s", strerror(errno));

	pid = spawn_rpicam(c, outpat, frames, interval);
	if (pid < 0) {
		r = errno;
		pss_log("burst %" PRIu64 ": fork: %s", id, strerror(r));
		reply(c, id, -r, 0);
		return;
	}
	c->b = (struct burst){
		.pid = pid,
		.event_id = id,
		.deadline_ns = now + (int64_t)frames * interval * PSS_NS_PER_MS + BURST_SLACK_NS,
	};
	c->bursts++;
	pss_log("burst %" PRIu64 " started: %" PRIu32 " frames every %" PRIu32 " ms (%s pid %d)",
		id, frames, interval, c->rpicam, (int)pid);
}

static uint32_t count_jpgs(const struct camd *c, uint64_t id)
{
	char tmp[48], path[PATH_MAX + 64];
	struct dirlist dl;
	uint32_t n = 0;
	int fd;

	if (clip_tmp_name(tmp, sizeof tmp, id) != 0)
		return 0;
	snprintf(path, sizeof path, "%s/%s", c->clips_path, tmp);
	fd = open(path, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
	if (fd < 0) {
		pss_log("burst %" PRIu64 ": open %s: %s", id, path, strerror(errno));
		return 0;
	}
	if (dirlist_read(fd, &dl) == 0) {
		for (size_t i = 0; i < dl.n; i++) {
			size_t len = strlen(dl.names[i]);

			if (len > 4 && strcmp(dl.names[i] + len - 4, ".jpg") == 0)
				n++;
		}
		dirlist_free(&dl);
	}
	if (close(fd) != 0)
		pss_log("close %s: %s", path, strerror(errno));
	return n;
}

static void reap_children(struct camd *c)
{
	for (;;) {
		int st;
		pid_t pid = waitpid(-1, &st, WNOHANG);

		if (pid == 0)
			return;
		if (pid < 0) {
			if (errno != ECHILD)
				pss_log("waitpid: %s", strerror(errno));
			return;
		}
		if (pid != c->b.pid)
			continue;

		int32_t status = WIFEXITED(st) ? WEXITSTATUS(st) : 128 + WTERMSIG(st);
		uint32_t frames = count_jpgs(c, c->b.event_id);

		if (status == 0 && frames > 0) {
			pss_log("burst %" PRIu64 " done: %" PRIu32 " frames", c->b.event_id, frames);
		} else {
			c->failures++;
			pss_log("%s exit %" PRId32 "; burst %" PRIu64 " skipped (%" PRIu32 " frames)",
				c->rpicam, status, c->b.event_id, frames);
			if (status == 0)
				status = -ENODATA;
		}
		reply(c, c->b.event_id, status, frames);
		c->b = (struct burst){ 0 };
	}
}

static void send_heartbeat(struct camd *c)
{
	struct pss_msg m;

	pss_msg_init(&m, PSS_MSG_HEARTBEAT);
	m.u.hb.dropped = c->cl.dropped;
	m.u.hb.count = c->bursts;
	client_send(&c->cl, &m);
}

/* Never leave an rpicam-still behind across our own restart. */
static void kill_burst(struct camd *c)
{
	int st;

	if (c->b.pid <= 0)
		return;
	if (kill(c->b.pid, SIGKILL) != 0 && errno != ESRCH)
		pss_log("kill %d: %s", (int)c->b.pid, strerror(errno));
