		s->sin_t[k] = (float)sin(2.0 * M_PI * k / PSS_FFT_N);
	}
	/* Edges f_b = 100 Hz * 80^(b/8): 100, 173, 299, 518, 894, 1546, 2675, 4627, 8000 Hz. */
	for (unsigned b = 0; b < PSS_NBANDS; b++) {
