	if (r != 0) {
		fprintf(stderr, "pss: could not read the event log in %s\n", data);
		return 1;
	}
	printf("-- %" PRIu64 " events, %" PRIu64 " boots, %" PRIu64 " stats records%s\n",
	       c.events, c.boots, c.stats, c.unknown ? " (some records of unknown type skipped)" : "");
	return 0;
}

